import React from "react";
import Navbar from "../components/Navbar";

export default function Services() {
  return (
    <div>
      <Navbar />
      <div style={{ padding: "30px" }}>
        <h1>Our Services</h1>
        <ul>
          <li>Electrician</li>
          <li>Plumber</li>
          <li>House Cleaning</li>
          <li>Appliance Repair</li>
          <li>Gardening</li>
        </ul>
      </div>
    </div>
  );
}
